use vstd::prelude::*;

verus! {

    /// Given 1 ≤ n ≤ 127, returns
    ///  - `[n/3, 0, 0]`            if n ≡ 0 (mod 3),
    ///  - `[(n−7)/3, 0, 1]`        if n ≡ 1 (mod 3) and n ≥ 7,
    ///  - `[(n−5)/3, 1, 0]`        if n ≡ 2 (mod 3) and n ≥ 5,
    ///  - `[-1]`                   otherwise (i.e. n=1,2,4).
    ///
    /// The `ensures` clause exactly pins down this behavior.
    fn solve(n: i8) -> (res: Vec<i8>)
        requires
            1 <= n && n <= 127,
        ensures
            if n % 3 == 0 {
                // n divisible by 3
                res == vec![n/3,  0,    0]
            } else if n % 3 == 1 {
                // n ≡ 1 mod 3
                if n < 7 {
                    // no nonneg solution for n=1,4
                    res == vec![-1]
                } else {
                    res == vec![(n - 7)/3,  0,  1]
                }
            } else {
                // n ≡ 2 mod 3
                if n < 5 {
                    // no nonneg solution for n=2
                    res == vec![-1]
                } else {
                    res == vec![(n - 5)/3,  1,  0]
                }
            },
    {
        let r = n % 3;
        if r == 0 {
            // divisible by 3
            let a = n / 3;
            res = vec![a, 0, 0];
        } else if r == 1 {
            // remainder 1
            if n < 7 {
                // only n=1 or 4, no solution
                res = vec![-1];
            } else {
                let a = (n - 7) / 3;
                res = vec![a, 0, 1];
            }
        } else {
            // remainder 2
            if n < 5 {
                // only n=2, no solution
                res = vec![-1];
            } else {
                let a = (n - 5) / 3;
                res = vec![a, 1, 0];
            }
        }
    }

}

